    "nginx": (3.35, 2.2, 17.35, 19.6),
    "perl": (2.65, 0, 18.7, 24),
    "php": (0, 5.7, 24, 12.65),
    "phpmyadmin": (0.05, 3.5, 23.9, 17.05),
    "prestashop": (0, 1.05, 24, 21.95),
    "wordpress": (0, 0, 24, 24),
    "xampp": (0.1, 0, 23.8, 24),
]
let LOGO_OVER: CGFloat = 1.2

/// El recuadro de cada trazo (el de su logotipo; las partes de uno en varios colores, el del logotipo entero)
let LOGO_BOX_FOR: [String: (CGFloat, CGFloat, CGFloat, CGFloat)] = {
    var m: [String: (CGFloat, CGFloat, CGFloat, CGFloat)] = [:]
    for (k, d) in LOGO_PATHS { if let b = LOGO_BOX[k] { m[d] = b } }
    for (k, parts) in LOGO_PARTS { if let b = LOGO_BOX[k] { for p in parts { m[p.0] = b } } }
    return m
}()

/// Dibuja el trazo de un logotipo (solo M, L, C y Z) escalado a su marco
struct LogoShape: Shape {
    let d: String
    func path(in rect: CGRect) -> Path {
        var p = Path()
        let t = d.split(separator: " ")
        var i = 0
        func num(_ k: Int) -> CGFloat {
            return i + k < t.count ? CGFloat(Double(t[i + k]) ?? 0) : 0
        }
        while i < t.count {
            let c = t[i]
            i += 1
            if c == "M" {
                p.move(to: CGPoint(x: num(0), y: num(1)))
                i += 2
            } else if c == "L" {
                p.addLine(to: CGPoint(x: num(0), y: num(1)))
                i += 2
            } else if c == "C" {
                p.addCurve(to: CGPoint(x: num(4), y: num(5)), control1: CGPoint(x: num(0), y: num(1)),
                           control2: CGPoint(x: num(2), y: num(3)))
                i += 6
            } else if c == "Z" {
                p.closeSubpath()
            }
        }
        // (su contorno real, centrado: todos con la misma superficie; los apaisados se salen un poco por los lados)
        let b = LOGO_BOX_FOR[d] ?? (0, 0, 24, 24)
        let long = Swift.max(b.2, b.3), short = Swift.max(0.1, Swift.min(b.2, b.3))
        let extra = Swift.min(LOGO_OVER, (long / short).squareRoot())
        let k = Swift.min(rect.width, rect.height) * extra / long
        let move = CGAffineTransform(translationX: rect.midX, y: rect.midY)
        return p.applying(move.scaledBy(x: k, y: k).translatedBy(x: -(b.0 + b.2 / 2), y: -(b.1 + b.3 / 2)))
    }
}

/// Icono de color, como en Ajustes del Sistema: símbolo blanco sobre un cuadrado redondeado. Con
/// «logo:<paquete>», el logotipo original del paquete en blanco sobre el color de su marca
struct ColorIcon: View {
    let symbol: String
    let color: Color
    var size: CGFloat = 22
    var body: some View {
        RoundedRectangle(cornerRadius: size * 0.27)
            .fill(LinearGradient(colors: [color.opacity(0.8), color], startPoint: .top, endPoint: .bottom))
            .frame(width: size, height: size)
            .overlay(glyph())
    }

    @ViewBuilder
    func glyph() -> some View {
        if symbol.hasPrefix("logo:") {
            LogoShape(d: LOGO_PATHS[String(symbol.dropFirst(5))] ?? "")
                .fill(Color.white)
                .frame(width: size * 0.64, height: size * 0.64)
        } else {
            Image(systemName: symbol)
                .font(.system(size: size * 0.5, weight: .semibold))
                .foregroundColor(.white)
        }
    }
}

/// Icono del logotipo de un paquete
func LogoIcon(_ name: String, size: CGFloat = 22) -> ColorIcon {
    return ColorIcon(symbol: "logo:" + name, color: brand(name), size: size)
}

