        _ = model.runTask(v ? "Poniendo WP-CLI en Docker" : "Quitando WP-CLI de Docker",
                          ["docker-wp-cli", v ? "si" : "no"] + (r.checked ? ["--rehacer"] : []),
                          doneText: "WP-CLI en Docker " + (v ? "puesto" : "quitado"), autoClose: !r.checked) { _, _, _ in read() }
    }
}

