                Button("Clonar") {}
                    .buttonStyle(OutlineButton())
                    .disabled(true)
                    .tip("Ya hay una carpeta con ese nombre")
            } else {
                Button("Clonar") { model.fetchRepo(item) }
                    .buttonStyle(OutlineButton(kind: "primary"))
                    .busyGuard(model.busy)
                    .tip("Clonar por SSH en htdocs")
